package com.docuflow.controller;
import com.docuflow.dto.DocumentDtos.*; import com.docuflow.entity.User; import com.docuflow.service.DocumentService; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/documents") public class DocumentController { private final DocumentService service; public DocumentController(DocumentService service){this.service=service;} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) public DocumentResponse upload(@RequestPart("data") @Valid CreateRequest req,@RequestPart("file") MultipartFile file,@AuthenticationPrincipal User user){return service.upload(req,file,user);} @GetMapping public Page<DocumentResponse> list(@AuthenticationPrincipal User u,@RequestParam(defaultValue="") String search,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable page){return service.list(u,search,page);}@GetMapping("/{id}") public DocumentResponse get(@PathVariable Long id,@AuthenticationPrincipal User u){return service.get(id,u);}@PatchMapping("/{id}/decision") public DocumentResponse decide(@PathVariable Long id,@Valid @RequestBody DecisionRequest req,@AuthenticationPrincipal User u){return service.decide(id,req,u);}@PostMapping("/{id}/sign") public DocumentResponse sign(@PathVariable Long id,@AuthenticationPrincipal User u){return service.sign(id,u);}@GetMapping("/{id}/comments") public List<CommentResponse> comments(@PathVariable Long id,@AuthenticationPrincipal User u){return service.comments(id,u);}@PostMapping("/{id}/comments") public CommentResponse comment(@PathVariable Long id,@Valid @RequestBody CommentRequest req,@AuthenticationPrincipal User u){return service.comment(id,req,u);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal User u){service.delete(id,u);} }
